mapper.select:
SELECT id, conversation_id, user_id, workflow_id, status, current_step, plan_json,
       plan_hash, confirmation_id, result, reply_saved, lease_owner, lease_until, error_code, error_message,
       created_at, updated_at
FROM ai_task_run
WHERE user_id = #{userId}
  AND id = #{id}

SELECT id, conversation_id, user_id, workflow_id, status, current_step, plan_json,
       plan_hash, confirmation_id, result, reply_saved, lease_owner, lease_until, error_code, error_message,
       created_at, updated_at
FROM ai_task_run
WHERE user_id = #{userId}
  AND confirmation_id = #{confirmationId}

mapper.update:
UPDATE ai_task_run
SET status = 'WAITING_CONFIRM', confirmation_id = #{confirmationId},
    plan_hash = COALESCE(#{planHash}, plan_hash), updated_at = now()
WHERE user_id = #{userId}
  AND id = #{id}
  AND status IN ('PLANNING', 'WAITING_CONFIRM', 'FAILED')

UPDATE ai_task_run
SET status = 'RUNNING', confirmation_id = COALESCE(#{confirmationId}, confirmation_id),
    updated_at = now(), error_code = NULL, error_message = NULL
WHERE user_id = #{userId}
  AND id = #{id}
  AND status IN ('PLANNING', 'WAITING_CONFIRM', 'RUNNING', 'FAILED', 'PARTIAL_FAILED')

UPDATE ai_task_run
SET status = #{status}, current_step = #{currentStep},
    error_code = #{errorCode}, error_message = #{errorMessage}, updated_at = now()
WHERE user_id = #{userId}
  AND id = #{id}

UPDATE ai_task_run
SET current_step = GREATEST(current_step, #{currentStep}), updated_at = now()
WHERE user_id = #{userId}
  AND id = #{id}

UPDATE ai_task_run
SET result = #{result}, updated_at = now()
WHERE user_id = #{userId}
  AND id = #{id}

UPDATE ai_task_run
SET reply_saved = TRUE, updated_at = now()
WHERE user_id = #{userId}
  AND id = #{id}

UPDATE ai_task_run
SET lease_owner = NULL, lease_until = NULL, updated_at = now()
WHERE id = #{id}
  AND lease_owner = #{owner}

UPDATE ai_task_run
SET lease_until = now() + make_interval(secs => #{leaseSeconds}), updated_at = now()
WHERE id = #{id}
  AND lease_owner = #{owner}
  AND status IN ('PLANNING', 'WAITING_CONFIRM', 'RUNNING')
